function binKA(l,kl){return !!l&&klassenAdmins(kl).some(u=>u.id===l.id)}
/* Startpasswort neu vergeben: wer sich noch nie angemeldet hat, bleibt bei "start" (Kinder dürfen dann wie beim ersten Mal frei wählen), sonst "reset" */
function startGrund(u){return pwStatus(u)==="start"?"start":"reset"}
function darfPwNeu(u){return !!u&&u.aktiv!==false&&(st.role==="admin"||(st.role==="lehrkraft"&&u.rolle==="s"&&binKA(T1,u.klasse)))}
function pwNeuSetzen(u){const pw=kontoStart(u,startGrund(u));u.angemeldet=false;meldungen().filter(m=>m.typ==="pw"&&m.u===u.id&&!m.erledigt).forEach(m=>{m.erledigt=Date.now()});return pw}

if(d.act==="karten"){closeModal();go("karten",{ids:d.ids.split(",")});return}
 if(d.act==="karten-pw"){const us=d.ids.split(",").map(U).filter(u=>u&&pwStatus(u)!=="eigen"&&darfPwNeu(u));if(!us.length)return;
  modal(`<h2>Neue Startpasswörter für ${us.length===1?esc(us[0].vn+" "+us[0].nn):us.length+" Personen"}?</h2><p>${us.length===1?"Das alte Startpasswort gilt":"Die alten Startpasswörter gelten"} dann nicht mehr. Wer sich noch nie angemeldet hat, kann beim ersten Mal wie bisher ein eigenes Passwort festlegen.</p><div class="note warn">Die neuen Passwörter sind nur jetzt sichtbar. Drucke die Kärtchen gleich oder speichere sie als PDF.</div><div class="actions"><button class="btn primary" data-act="karten-pw-ok" data-ids="${us.map(u=>u.id).join(",")}">Erzeugen</button><button class="btn ghost" data-close-btn>Abbrechen</button></div>`);return}
 if(d.act==="karten-pw-ok"){const us=d.ids.split(",").map(U).filter(u=>u&&pwStatus(u)!=="eigen"&&darfPwNeu(u));us.forEach(pwNeuSetzen);closeModal();toast(`${us.length} neue ${us.length===1?"Startpasswort":"Startpasswörter"} erzeugt – jetzt drucken oder als PDF speichern.`);render();return}
